package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;
public final class WalletActivity extends Activity {
 protected void attachBaseContext(Context c){super.attachBaseContext(I18n.localized(c));}
 private void styleBars(){int v=WebTheme.isDark(this)?1:0;getWindow().setStatusBarColor(WebDesign.BG[v]);getWindow().setNavigationBarColor(WebDesign.BG[v]);getWindow().getDecorView().setSystemUiVisibility(v==0?View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0);}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String s,int size,int color){TextView t=new KinnectText(this);t.setText(I18n.t(s));t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(8));return t;}
 public void onCreate(Bundle b){super.onCreate(b);styleBars();NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);setContentView(label("Đang tải…",16,0xff6c47e0));NativeApi.shared.call("GET","/api/wallet",null,(data,error,status)->{if(isDestroyed())return;if(error!=null){setContentView(label(error,16,0xff6c47e0));return;}draw(data);});}
 private void draw(JSONObject w){int v=WebTheme.isDark(this)?1:0,ink=WebDesign.INK[v];ScrollView scroll=new ScrollView(this);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(20),dp(12),dp(20),dp(24));page.setBackgroundColor(WebDesign.BG[v]);scroll.addView(page);scroll.setOnApplyWindowInsetsListener((view,i)->{view.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});setContentView(scroll);TextView back=label("‹  Ví Kinnect",22,ink);back.setOnClickListener(x->finish());page.addView(back);LinearLayout balance=new LinearLayout(this);balance.setOrientation(1);balance.setPadding(dp(24),dp(18),dp(24),dp(18));GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff5b21b6,0xffc026d3});gradient.setCornerRadius(dp(24));balance.setBackground(gradient);balance.addView(label("VÍ KINNECT",12,Color.WHITE));balance.addView(label(w.optLong("coins")+" "+I18n.t("xu"),36,Color.WHITE));page.addView(balance);page.addView(action("Nạp xu"));page.addView(label("Thu nhập từ Live",16,ink));page.addView(label(java.text.NumberFormat.getIntegerInstance(new java.util.Locale("vi","VN")).format(w.optLong("earningsVnd"))+"đ",32,ink));page.addView(label("Bạn nhận 75% · Nền tảng 25%",13,WebDesign.MUTED[v]));page.addView(action("Rút tiền"));page.addView(label("Đang kết nối thanh toán và chi trả tự động. Chưa mở nạp hoặc rút tiền.",12,WebDesign.MUTED[v]));page.addView(label("Lịch sử giao dịch",18,ink));JSONArray entries=w.optJSONArray("entries");if(entries==null||entries.length()==0)page.addView(label("Chưa có giao dịch",14,WebDesign.MUTED[v]));else for(int n=0;n<entries.length();n++){JSONObject e=entries.optJSONObject(n);page.addView(label(I18n.t("Thu nhập quà tặng")+" · "+e.optLong("creatorVnd")+"đ",14,ink));}page.addView(label("Tỷ lệ chia áp dụng sau phí thanh toán và hoàn tiền.",12,WebDesign.MUTED[v]));}
 private Button action(String title){Button b=new Button(this);b.setText(I18n.t(title));b.setAllCaps(false);b.setOnClickListener(v->new Sheet(this).setTitle(I18n.t(title)).setMessage(I18n.t("Chưa kết nối dịch vụ thanh toán và chi trả. Không phát sinh giao dịch.")).setPositiveButton(I18n.t("Đóng"),null).show());return b;}
}
